typedef unsigned int uint32;

struct vector3d
{
    float x, y, z;
};

struct vector4d
{
    float x, y, z, w;
};

struct po
{
    vector4d data[4];
};

struct color32
{
    uint32 value;
};

struct frame_info
{
    char data[12];
    frame_info& operator=(const frame_info&);
};

__asm__(".equ __as__10frame_infoRC10frame_info,0x00338678");

class instance_render_info
{
public:
    bool operator<(const instance_render_info& iri) const
    {
        return frame < iri.frame;
    }

    instance_render_info& operator=(const instance_render_info& new_guy)
    {
        if (&new_guy == this)
            return *this;

        number_of_faces_to_attempt = new_guy.number_of_faces_to_attempt;
        local_to_world = new_guy.local_to_world;
        force_flags = new_guy.force_flags;
        color_scale = new_guy.color_scale;
        camera_relative_rotation = new_guy.camera_relative_rotation;
        frame_time_info = new_guy.frame_time_info;
        my_region = new_guy.my_region;
        particle_scale = new_guy.particle_scale;
        my_light_set = new_guy.my_light_set;
        alt_materials = new_guy.alt_materials;
        frame = new_guy.frame;
        render_scale = new_guy.render_scale;
        return *this;
    }

    float number_of_faces_to_attempt;
    po local_to_world;
    uint32 force_flags;
    color32 color_scale;
    float camera_relative_rotation;
    frame_info frame_time_info;
    void* my_region;
    float particle_scale;
    void* my_light_set;
    void* alt_materials;
    int frame;
    vector3d render_scale;
};

template <class T>
inline void swap(T& a, T& b)
{
    T tmp = a;
    a = b;
    b = tmp;
}

template <class ForwardIterator1, class ForwardIterator2>
inline void iter_swap(ForwardIterator1 a, ForwardIterator2 b)
{
    swap(*a, *b);
}

extern "C" instance_render_info* partition_instances(
    instance_render_info* first,
    instance_render_info* last,
    const instance_render_info& pivot
) __asm__(
    "__unguarded_partition__H2ZP20instance_render_info"
    "Z20instance_render_info_X01X01X11_X01"
);

instance_render_info* partition_instances(
    instance_render_info* first,
    instance_render_info* last,
    const instance_render_info& pivot
)
{
    while (1) {
        while (*first < pivot)
            ++first;
        --last;
        while (pivot < *last)
            --last;
        if (!(first < last))
            return first;
        iter_swap(first, last);
        ++first;
    }
}
